 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 ticket:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4z"/><path d="M12 5v14" stroke-dasharray="2 2"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v6m0-10v1"/>',
 gift:'<rect x="3" y="10" width="18" height="11" rx="1"/><path d="M3 10h18V7H3zM12 7v14M12 7S5 7 5 4c0-4 7-2 7 3zm0 0s7 0 7-3c0-4-7-2-7 3z"/>',
 close:'<path d="M5 5l14 14M19 5 5 19"/>',
 qr:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><path d="M14 15h3v3h-3zM21 14v7h-4m-1 0h-2"/>',
 shield:'<path d="M12 2 4 5v6c0 5 3 8.5 8 11 5-2.5 8-6 8-11V5z"/><path d="m9 12 2 2 4-4"/>',
 trophy:'<path d="M7 3h10v7a5 5 0 0 1-10 0zm0 2H4v3a4 4 0 0 0 4 4m9-7h3v3a4 4 0 0 1-4 4M12 15v4m-5 2h10"/>',
 crown:'<path d="m3 8 4 4 5-7 5 7 4-4-2 11H5z"/>',
